import React, { useState } from 'react';
import { Mail, Phone, MapPin, UserCheck, ShieldCheck, Sparkles, FileText, Star, ChevronRight } from 'lucide-react';

const skills = [
  { id: 1, name: 'Machine Learning', icon: Sparkles, level: '95%' },
  { id: 2, name: 'Natural Language Processing', icon: FileText, level: '90%' },
  { id: 3, name: 'Computer Vision', icon: Sparkles, level: '85%' },
  { id: 4, name: 'Full-stack Development', icon: FileText, level: '92%' },
  { id: 5, name: 'Real-time Analytics', icon: Sparkles, level: '88%' },
  { id: 6, name: 'DevOps & CI/CD', icon: FileText, level: '94%' }
];

const experiences = [
  {
    id: 1,
    company: 'Scale AI',
    title: 'Senior AI Engineer',
    period: 'Sep 2021 - Present',
    role: 'Building large-scale NLP and CV pipelines for enterprise clients.',
    highlights: [
      'Developed a real-time event detection system reducing false positives by 40%.',
      'Optimized model inference times by 25% using optimized microservices.',
      'Scaled a multi-tenant storage solution, reducing cold start latency.'
    ]
  },
  {
    id: 2,
    company: 'Kaggle',
    title: 'Top Kaggle Competitor',
    period: 'Ongoing',
    role: 'Participating in public competitions, contributing to forums.',
    highlights: [
      'Top 1% in the Home Prices Kaggle competition.',
      'Won the NLP Workshop leaderboard with an ensemble model.'
    ]
  }
];

export default function About() {
  const [isContactOpen, setIsContactOpen] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });

  const handleFormChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Simulate a submission
    setTimeout(() => {
      setIsContactOpen(false);
      alert('Message sent! Thanks for reaching out.');
    }, 1200);
  };

  return (
    <div className="w-full min-h-[800px] bg-slate-950 text-slate-100 font-sans antialiased">
      {/* Decorative gradient header */}
      <div className="w-full h-48 bg-gradient-to-br from-indigo-950 via-purple-950 to-transparent relative z-0" />

      {/* Card grid for skills & experience */}
      <div className="max-w-7xl mx-auto p-6 sm:p-10">
        <h2 className="text-3xl font-bold tracking-tight text-slate-100 bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 via-purple-500 to-pink-600 mb-10 text-center">
          About Me & My Capabilities
        </h2>

        {/* Skill badges */}
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 mb-8">
          {skills.map((skill) => (
            <div 
              key={skill.id}
              className="py-3 px-4 rounded-xl bg-white/5 border border-white/10 flex items-center gap-2 shadow-lg transition-all duration-300 hover:scale-[1.02] hover:shadow-indigo-500/10"
            >
              <div className="w-5 h-5 text-indigo-400 flex-shrink-0"><skill.icon size={16} /></div>
              <div className="text-sm font-medium text-slate-300">{skill.name}</div>
              <span className="inline-flex items-center justify-center w-12 h-6 text-[10px] font-semibold text-white bg-indigo-500/20 rounded-full ml-auto">{skill.level}</span>
            </div>
          ))}
        </div>

        {/* Experience timeline */}
        <div className="space-y-6">
          {experiences.map((exp) => (
            <div key={exp.id} className="p-6 rounded-2xl bg-white/5 border border-white/10 shadow-lg transition-all duration-300 hover:scale-[1.01] hover:shadow-indigo-500/10">
              <div className="flex items-start justify-between pb-4 border-b border-white/10 mb-4">
                <div className="flex items-center space-x-2">
                  <div className="p-2 rounded-xl bg-indigo-500/20 text-indigo-400"><MapPin size={16} /></div>
                  <div>
                    <h3 className="font-bold text-slate-200">{exp.company}</h3>
                    <p className="text-slate-400 text-sm">{exp.title}</p>
                  </div>
                </div>
                <div className="flex flex-col items-end space-y-1">
                  <p className="text-slate-400 text-sm tracking-wider">{exp.period}</p>
                  <span className="inline-flex items-center gap-1 text-sm text-indigo-400 bg-indigo-500/20 px-2 rounded-full">
                    <Sparkles size={12} /> {exp.id}
                  </span>
                </div>
              </div>
              <div>
                <p className="text-slate-400 text-sm mb-4">{exp.role}</p>
                {exp.highlights.map((h, i) => (
                  <p key={i} className="text-slate-400 text-sm flex items-start gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-500/20"></div>
                    {h}
                  </p>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Decorative footer section */}
      <div className="w-full h-48 bg-gradient-to-br from-purple-950 via-indigo-950 to-transparent relative z-0" />

      {/* Contact CTA */}
      <div className="max-w-7xl mx-auto p-6 sm:p-10 bg-slate-900/80 backdrop-blur-xl rounded-2xl border border-white/10 mt-20">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6 mb-10">
          <div>
            <h3 className="text-xl font-bold text-slate-100">Get in Touch</h3>
            <p className="text-slate-400 text-sm mt-2">Ready to build something amazing?</p>
          </div>
          <button
            onClick={() => setIsContactOpen(true)}
            className="inline-flex items-center gap-2 py-3 px-6 rounded-xl bg-indigo-600/10 border border-indigo-500/20 hover:bg-indigo-600/20 text-slate-100 font-semibold transition-all duration-300 active:scale-[0.98] active:shadow-none"
          >
            <Mail size={18} /> Connect
          </button>
        </div>

        {/* Contact Form Modal */}
        {isContactOpen && (
          <form onSubmit={handleSubmit} className="space-y-4 sm:w-[400px]">
            <div className="grid grid-cols-1 sm:grid-cols-2 sm:gap-4">
              <div className="relative z-10">
                <label htmlFor="name" className="block text-slate-400 text-sm mb-2">Full Name</label>
                <input 
                  type="text" 
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleFormChange}
                  className="w-full py-2 pl-6 pr-12 bg-slate-900/30 border border-slate-700 rounded-xl text-slate-100 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                  placeholder="Amey Chikane"
                  required
                />
                <div className="absolute right-3 top-2.5 p-1 rounded-xl bg-white/5 text-slate-400"><UserCheck size={14} /></div>
              </div>

              <div className="relative z-10">
                <label htmlFor="email" className="block text-slate-400 text-sm mb-2">Email Address</label>
                <input 
                  type="email" 
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleFormChange}
                  className="w-full py-2 pl-6 pr-12 bg-slate-900/30 border border-slate-700 rounded-xl text-slate-100 focus:ring-2 focus:ring-indigo-500/50 outline-none transition-all"
                  placeholder="ameychikane@scale.ai"
                  required
                />
                <div className="absolute right-3 top-2.5 p-1 rounded-xl bg-white/5 text-slate-400"><Mail size={14} /></div>
              </div>
            </div>

            <textarea 
              name="message"
              value={formData.message}
              onChange={handleFormChange}
              className="w-full py-4 px-6 bg-slate-900/30 border border-slate-700 rounded-xl text-slate-100 focus:ring-2 focus:ring-indigo-500/50 outline-none resize-y min-h-[100px] max-h-[300px] text-sm font-sans"
              placeholder="Briefly describe your project..."
              required
            ></textarea>

            <button 
              type="submit"
              className="w-full py-3 rounded-xl bg-indigo-600/10 border border-indigo-500/20 hover:bg-indigo-600/20 text-slate-100 font-semibold transition-all duration-300 active:scale-[0.98] active:shadow-none"
            >
              <span className="inline-flex items-center gap-2">
                <Sparkles size={18} /> Send Message
              </span>
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Star, Sparkles, FileText, Globe, Sparkle, Package, User, Clock, Code, ExternalLink, ArrowUpRight, CheckCircle2, SlidersHorizontal, XCircle, Circle as SparkleOff } from 'lucide-react';

const MOCK_PROJECTS = [
  {
    id: 1,
    name: "AI Resume Optimizer",
    description: "A full-stack application that analyzes user resumes and suggests tailored language adjustments to optimize for top-tier tech job listings.",
    stack: ["React", "Node.js", "Firestore", "MLflow"],
    role: "Full-stack Developer",
    timeframe: "Oct - Dec 2023",
    impact: "Increased candidate response rates by 30% by improving match quality.",
    status: "Deployed & Live"
  },
  {
    id: 2,
    name: "SynapseML Hub",
    description: "A collaborative workspace for data scientists to share & deploy machine learning models, featuring version control and real-time model tracking.",
    stack: ["Next.js", "Docker", "TensorFlow", "Kubernetes"],
    role: "Backend Engineer",
    timeframe: "Apr - Sep 2023",
    impact: "Reduced time-to-deployment by 40% for team members.",
    status: "Enterprise Tier Available"
  },
  {
    id: 3,
    name: "VoiceBot Pro",
    description: "A voice-first customer service solution built for enterprise businesses, integrating NLU engines and real-time speech analytics.",
    stack: ["Twilio", "Next.js", "RapidAPI"],
    role: "Full-stack Developer",
    timeframe: "Jan - Mar 2023",
    impact: "Decreased average handling time by 25% for call centers.",
    status: "GA & Customer Base"
  },
  {
    id: 4,
    name: "GPT-Studio",
    description: "A low-code environment for developers to prototype and train custom GPT-like language models, with real-time code autocompletion and feedback.",
    stack: ["React Native", "AWS Lambda", "TensorFlow.js"],
    role: "Backend Engineer",
    timeframe: "Sep - Nov 2023",
    impact: "Empowered 50+ developers to build AI-powered apps without deep ML expertise.",
    status: "Private Beta"
  }
];

export default function Work() {
  const [filter, setFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);

  const filteredProjects = MOCK_PROJECTS.filter(p => {
    return p.name.toLowerCase().includes(searchTerm.toLowerCase()) &&
           (filter === 'All' || p.stack.includes(filter));
  });

  const handleDismiss = (id) => {
    setIsDismissed(id);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans antialiased">
      {/* Header Bar */}
      <div className="relative flex items-center justify-between px-6 py-8 sm:px-8">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-slate-100 sm:text-4xl">
            My Professional Work
          </h1>
          <p className="mt-2 text-sm text-slate-400">
            Selected projects showcasing the impact I've made.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="relative flex items-center gap-2 px-3 py-2 rounded-xl bg-white/5 border border-white/10 backdrop-blur-md hover:shadow-lg transition-all duration-300">
            <input 
              type="text" 
              placeholder="Search projects..." 
              className="w-full bg-transparent border-0 outline-none text-slate-300 placeholder:text-slate-500 focus:ring-0"
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-2 top-1.5 p-1 rounded-lg bg-white/5 hover:bg-white/10 text-slate-400 hover:text-slate-200 transition-all duration-200"
            >
              <XCircle size={16} />
            </button>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setFilter('All')}
              className="py-2.5 px-4 rounded-xl text-sm font-medium transition-colors duration-200 hover:underline active:text-white/70 disabled:opacity-50"
              style={filter === 'All' ? { backgroundColor: 'white/10', borderColor: 'white/20' } : { backgroundColor: 'transparent', borderColor: 'white/10' }}
            >
              All
            </button>
            <button 
              onClick={() => setFilter('React')}
              className="py-2.5 px-4 rounded-xl text-sm font-medium transition-colors duration-200 hover:underline active:text-white/70 disabled:opacity-50"
              style={filter === 'React' ? { backgroundColor: 'white/10', borderColor: 'white/20' } : { backgroundColor: 'transparent', borderColor: 'white/10' }}
            >
              React
            </button>
            <button 
              onClick={() => setFilter('ML')}
              className="py-2.5 px-4 rounded-xl text-sm font-medium transition-colors duration-200 hover:underline active:text-white/70 disabled:opacity-50"
              style={filter === 'ML' ? { backgroundColor: 'white/10', borderColor: 'white/20' } : { backgroundColor: 'transparent', borderColor: 'white/10' }}
            >
              ML
            </button>
            <button 
              onClick={() => setFilter('SaaS')}
              className="py-2.5 px-4 rounded-xl text-sm font-medium transition-colors duration-200 hover:underline active:text-white/70 disabled:opacity-50"
              style={filter === 'SaaS' ? { backgroundColor: 'white/10', borderColor: 'white/20' } : { backgroundColor: 'transparent', borderColor: 'white/10' }}
            >
              SaaS
            </button>
          </div>
        </div>
      </div>

      {/* Main Work Grid */}
      <div className="py-8 sm:py-12">
        <div className="mx-auto max-w-7xl px-6 sm:px-8">
          <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-3">
            {filteredProjects.map((project) => {
              const isDismissedProject = isDismissed.includes(project.id);
              return (
                <div 
                  key={project.id} 
                  className="group relative rounded-3xl border border-white/10 bg-slate-900/90 backdrop-blur-xl p-6 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:shadow-indigo-600/10"
                >
                  {isDismissedProject ? (
                    <div className="absolute -inset-0 bg-white/5 border border-white/10 backdrop-blur-xl animate-fade-out" />
                  ) : (
                    <>
                      {/* Top Gradient Accent */}
                      <div className="absolute -top-12 -left-12 w-96 h-96 bg-gradient-to-br from-indigo-600/20 to-purple-600/10 rounded-full blur-3xl pointer-events-none group-hover:translate-x-24 transition-transform duration-500" />
                      {/* Bottom Gradient Accent */}
                      <div className="absolute -bottom-12 -right-12 w-96 h-96 bg-gradient-to-tl from-indigo-600/20 to-purple-600/10 rounded-full blur-3xl pointer-events-none group-hover:translate-x-24 transition-transform duration-500" />

                      {/* Stack Badge */}
                      <div className="absolute -top-1 -right-1 bg-white/10 border border-white/20 rounded-full p-1 text-[10px] uppercase tracking-wider font-semibold text-slate-400">
                        {project.stack.map((stack, idx) => (
                          <span key={idx} className="bg-gradient-to-r from-indigo-500 to-purple-600 px-2 py-0.5 text-[10px] font-semibold text-white rounded-full mr-1">{stack}</span>
                        ))}
                      </div>

                      {/* Hover State Glow */}
                      <div className="absolute -inset-1 bg-white/5 rounded-3xl blur-3xl group-hover:scale-[1.03] transition-all duration-300" />

                      {/* Card Content */}
                      <div className="relative z-10 flex flex-col justify-between">
                        <div className="flex flex-col gap-2">
                          <h3 className="text-xl font-bold tracking-tight text-slate-100 group-hover:text-indigo-400 transition-colors duration-300">
                            {project.name}
                          </h3>
                          <p className="text-sm text-slate-400 flex items-center gap-1">
                            <User size={14} className="text-slate-400" /> {project.role}
                          </p>
                          <p className="text-sm text-slate-400 flex items-center gap-1">
                            <Clock size={14} className="text-slate-400" /> {project.timeframe}
                          </p>
                        </div>

                        {/* Stack & External Links */}
                        <div className="flex flex-wrap items-center gap-3 justify-end text-slate-400">
                          {project.stack.map((stack, idx) => (
                            <span key={idx} className="px-3 py-1 rounded-full bg-white/5 border border-white/10 text-[10px] tracking-wider font-semibold text-slate-400 flex items-center gap-1">
                              {stack}
                              <Sparkle size={10} />
                            </span>
                          ))}
                          {project.status !== 'Deployed & Live' && (
                            <button
                              onClick={() => setIsDismissed([...isDismissed, project.id])}
                              className="px-3 py-1 rounded-xl text-[10px] bg-white/5 border border-white/10 text-slate-400 hover:bg-white/10 transition-colors duration-200 flex items-center gap-1"
                            >
                              <XCircle size={14} /> {project.status}
                            </button>
                          )}
                        </div>
                      </div>

                      {/* Bottom Gradient Accent */}
                      <div className="absolute bottom-0 left-0 w-full h-24 bg-gradient-to-t from-indigo-600/10 to-transparent" />
                    </>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Footer Filters */}
      <div className="py-8 flex items-center justify-between px-6 sm:px-8">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1 px-3.5 py-2 rounded-xl bg-white/5 border border-white/10 text-slate-400 hover:text-slate-200 hover:bg-white/10 transition-colors duration-200">
            <Sparkles size={14} /> {filter === 'All' ? 'All Filters' : filter}
          </div>
          <button 
            onClick={() => setIsHovered(!isHovered)}
            className="p-2 rounded-lg bg-white/5 border border-white/10 text-slate-400 hover:bg-white/10 hover:text-slate-200 transition-colors duration-200"
          >
            <Sparkles size={14} />
          </button>
        </div>
        <div className="flex items-center gap-3">
          {isHovered && (
            <div className="w-64 bg-white/5 border border-white/10 rounded-xl p-3 backdrop-blur-xl text-slate-400 transition-colors duration-300 hover:bg-white/10">
              <div className="flex items-center gap-2 px-2 py-1 rounded-xl bg-white/10 border border-white/20 text-[10px] tracking-wider font-semibold text-slate-400 hover:bg-white/20">
                <Sparkles size={14} /> All Stack Filters
              </div>
              <div className="grid grid-cols-2 gap-2 p-2">
                {['React', 'Node.js', 'Next.js', 'Golang', 'MLflow'].map(tag => (
                  <div 
                    key={tag} 
                    className="px-3 py-1 rounded-xl bg-white/5 border border-white/10 text-[10px] tracking-wider font-semibold text-slate-400 hover:bg-white/10 hover:text-slate-200 transition-colors duration-200"
                  >
                    {tag}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
